#!/usr/bin/env python3
"""Run exact installer/layout/inference checks in a fresh namespace root."""
import argparse,json,os,pathlib,subprocess
p=argparse.ArgumentParser(description=__doc__);p.add_argument('--bundle',required=True,type=pathlib.Path);p.add_argument('--models',required=True,type=pathlib.Path);p.add_argument('--prepared',required=True,type=pathlib.Path);p.add_argument('--evidence',required=True,type=pathlib.Path);a=p.parse_args();bundle=a.bundle.resolve();e=a.evidence.resolve();e.mkdir(parents=True,exist_ok=True)
command=['/usr/bin/systemd-run','--user','--scope','--quiet','--unit=voxtype-selection-installed-'+str(os.getpid()),'-p','MemoryMax=3500M','-p','MemorySwapMax=0','-p','CPUQuota=200%',
 '/usr/bin/bwrap','--unshare-all','--die-with-parent','--new-session','--clearenv','--uid','0','--gid','0','--tmpfs','/','--dir','/usr','--ro-bind','/usr/bin','/usr/bin','--ro-bind','/usr/lib','/usr/lib','--symlink','usr/bin','/bin','--symlink','usr/lib','/lib','--symlink','usr/lib','/lib64','--ro-bind','/etc','/etc','--proc','/proc','--dev','/dev','--dev-bind','/dev/dri/renderD128','/dev/dri/renderD128','--ro-bind','/sys','/sys','--dir','/usr/local','--dir','/var/lib','--dir','/mnt/fixture','--dir','/run/user/1000','--dir','/scratch',
 '--ro-bind','/usr/share','/usr/share','--ro-bind',str(bundle),'/mnt/code','--ro-bind',str(a.prepared.resolve()),'/mnt/prepared.toml','--ro-bind',str(bundle/'tests/fixtures/vad'),'/mnt/fixtures','--ro-bind',str(a.models.resolve()),'/models','--ro-bind',str(a.models.resolve()),'/home/test/.local/share/voxtype/models','--bind',str(e),'/evidence',
 '--setenv','PATH','/usr/bin:/bin','--setenv','HOME','/home/test','--setenv','TMPDIR','/scratch','--setenv','XDG_RUNTIME_DIR','/run/user/1000','--setenv','DBUS_SESSION_BUS_ADDRESS','unix:path=/run/user/1000/absent-bus','/usr/bin/python3','/mnt/code/reproduce/test-installed-selection.py']
x=subprocess.run(command,capture_output=True,text=True,timeout=180);(e/'stdout').write_text(x.stdout);(e/'stderr').write_text(x.stderr);(e/'exit').write_text(str(x.returncode)+'\n');(e/'command.json').write_text(json.dumps(command,indent=2)+'\n');print(x.stdout+x.stderr);raise SystemExit(x.returncode)
